def __getattr__(name: str) -> Any:
    return getattr(baseline, name)

def _entrypoint_for_profile(profile: str) -> str:
    if profile == PROFILE_BASELINE_4201:
        return BASELINE_DISPATCHER_ENTRYPOINT
    return CANDIDATE_DISPATCHER_ENTRYPOINT

def _profile_entries(profile: str) -> tuple[dict[str, Any], ...]:
    if profile not in _VALID_PROFILES:
        raise ValueError(f'unknown be97 dispatcher profile: {profile}')
    if profile == PROFILE_BASELINE_4201:
        return ()
    return _D129_ENTRIES

def _guard_order(profile: str) -> list[str]:
    if profile not in _VALID_PROFILES:
        raise ValueError(f'unknown be97 dispatcher profile: {profile}')
    if profile == PROFILE_BASELINE_4201:
        return list(baseline._guard_order(baseline.PROFILE_ALL))
    return [*(str(entry['shape_key']) for entry in _D129_ENTRIES), *baseline._guard_order(baseline.PROFILE_ALL)]

def _uses_d129_seed(inputs: dict[str, Any]) -> bool:
    return d129_mtail.selected_route(inputs) in D129_ROUTES

def _baseline_info(inputs: dict[str, Any], profile: str) -> dict[str, Any]:
    info = dict(baseline.route_info(inputs))
    route = str(info.get('selected_route') or info.get('route') or baseline.selected_route(inputs))
    info['profile'] = profile
    info['route'] = route
    info['selected_route'] = route
    info['guard_order'] = _guard_order(profile)
    info.setdefault('production_policy', 'weave_only')
    info.setdefault('external_fallback', None)
    info.setdefault('coverage_only', False)
    info.setdefault('missing_weave_route', False)
    if info.get('classification') == 'seed-produced':
        info['classification'] = 'seed-consumed'
    return info

def _d129_info(inputs: dict[str, Any], profile: str) -> dict[str, Any]:
    source_info = dict(d129_mtail.route_info(inputs))
    parent_info = dict(baseline.route_info(inputs))
    parent_route = str(parent_info.get('selected_route') or parent_info.get('route') or baseline.selected_route(inputs))
    route = str(source_info.get('selected_route') or source_info.get('route') or d129_mtail.selected_route(inputs))
    info = dict(source_info)
    info.update({'profile': profile, 'route': route, 'selected_route': route, 'selected_entrypoint': _entrypoint_for_profile(profile), 'source_entrypoint': d129_mtail.ENTRYPOINT, 'parent_route': parent_route, 'replaced_route': parent_route, 'route_kind': 'specialized', 'route_source': 'shape-specific-seed', 'classification': 'seed-consumed', 'coverage_only': False, 'production_policy': 'weave_only', 'external_fallback': None, 'guard_order': _guard_order(profile), 'guard_condition': source_info.get('selected_guard') or source_info.get('guard_condition'), 'fallback': parent_route, 'missing_weave_route': False, 'source_task': CONSUMED_D129_SOURCE_TASK, 'source_round_doc': CONSUMED_D129_SOURCE_ROUND_DOC, 'selected_seed': CONSUMED_D129_B979_SEED, 'selected_seed_task': CONSUMED_D129_B979_SEED, 'expected_seed': CONSUMED_D129_B979_SEED, 'producer_seed': source_info.get('selected_seed') or CONSUMED_D129_PRODUCER_SEED, 'producer_seed_task': CONSUMED_D129_PRODUCER_SEED, 'replaced_seed': parent_info.get('selected_seed')})
    return info

def selected_route_for_profile(inputs: dict[str, Any], profile: str) -> str:
    if profile not in _VALID_PROFILES:
        raise ValueError(f'unknown be97 dispatcher profile: {profile}')
    if profile == PROFILE_B979_D129 and _uses_d129_seed(inputs):
        return d129_mtail.selected_route(inputs)
    return baseline.selected_route(inputs)

def selected_route(inputs: dict[str, Any]) -> str:
    return selected_route_for_profile(inputs, PROFILE_ALL)

def selected_route_name(inputs: dict[str, Any]) -> str:
    return selected_route(inputs)

def route_info_for_profile(inputs: dict[str, Any], profile: str) -> dict[str, Any]:
    if profile not in _VALID_PROFILES:
        raise ValueError(f'unknown be97 dispatcher profile: {profile}')
    if profile == PROFILE_B979_D129 and _uses_d129_seed(inputs):
        return _d129_info(inputs, profile)
    return _baseline_info(inputs, profile)

def route_info(inputs: dict[str, Any]) -> dict[str, Any]:
    return route_info_for_profile(inputs, PROFILE_ALL)

def route_trace_entry(label: str, inputs: dict[str, Any], profile: str=PROFILE_ALL) -> dict[str, Any]:
    return {'label': label, 'shape_key': label, 'B': int(inputs['B']), 'Q': int(inputs['Q']), 'M': int(inputs['M']), 'D': int(inputs['D']), 'K': int(inputs['K']), 'self_search': bool(inputs.get('self_search', False)), 'force_fallback': bool(inputs.get('force_fallback', False)), **route_info_for_profile(inputs, profile)}

def launch_for_profile(inputs: dict[str, Any], profile: str) -> dict[str, Any]:
    if profile == PROFILE_B979_D129 and _uses_d129_seed(inputs):
        return d129_mtail.launch_for_eval(inputs)
    return baseline.launch_for_eval(inputs)

def launch_baseline_for_eval(inputs: dict[str, Any]) -> dict[str, Any]:
    return launch_for_profile(inputs, PROFILE_BASELINE_4201)

